@using sv_8e752b5dbb4e437990ff55b986d51574.Services

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    @if (Security is null)
    {
        <p class="text-muted">Loading...</p>
        return;
    }

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <hr class="my-4" />

    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <h6 class="mb-1">Two-Factor Authentication</h6>
                <p class="text-muted small mb-0">Add an extra layer of security to your account.</p>
            </div>
            <div class="d-flex align-items-center gap-2">
                <span class="badge @(Security.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(Security.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
                <div class="form-check form-switch mb-0">
                    <input class="form-check-input" type="checkbox" role="switch"
                           checked="@Security.TwoFactorEnabled" disabled
                           title="Contact admin to change 2FA settings" />
                </div>
            </div>
        </div>
    </div>

    @if (Security.LastPasswordChange.HasValue)
    {
        <p class="text-muted small">
            Last password change: @Security.LastPasswordChange.Value.ToString("MMMM d, yyyy")
        </p>
    }

    <hr class="my-4" />

    <ActiveSessionsTable Sessions="Security.Sessions"
                         CurrentSessionId="@_currentSessionId"
                         OnRevokeRequested="ShowRevokeDialog" />

    <RevokeSessionDialog Session="_sessionToRevoke"
                         OnConfirm="HandleRevoke"
                         OnCancel="() => _sessionToRevoke = null" />
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings? Security { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private ActiveSession? _sessionToRevoke;
    private string _currentSessionId = "sess-1";

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await OnChangePassword.InvokeAsync(args);
    }

    private void ShowRevokeDialog(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task HandleRevoke(string sessionId)
    {
        await OnRevokeSession.InvokeAsync(sessionId);
        _sessionToRevoke = null;
    }
}

