+                        <div class="form-check form-check-inline">
+                            <input class="form-check-input" type="radio" name="fontSize"
+                                   id="@($"fs-{size}")" value="@size"
+                                   checked="@(_fontSize == size)"
+                                   @onchange="() => _fontSize = size" />
+                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
+                        </div>
+                    }
+                </div>
+            </div>
+
+            <div class="card mb-4">
+                <div class="card-body">
+                    <h6 class="card-title mb-3">Language</h6>
+                    <select class="form-select" @bind="_language">
+                        @foreach (var lang in _languages)
+                        {
+                            <option value="@lang">@lang</option>
+                        }
+                    </select>
+                </div>
+            </div>
+
+            <div class="card mb-4">
+                <div class="card-body d-flex justify-content-between align-items-center">
+                    <div>
+                        <h6 class="mb-1">Compact Mode</h6>
+                        <p class="text-muted small mb-0">Reduce spacing and padding throughout the UI.</p>
+                    </div>
+                    <div class="form-check form-switch mb-0">
+                        <input class="form-check-input" type="checkbox" role="switch"
+                               checked="@_compactMode"
+                               @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
+                    </div>
+                </div>
+            </div>
+
+            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
+                @if (_saving)
+                {
+                    <span class="spinner-border spinner-border-sm me-1"></span>
+                }
+                Save
+            </button>
+        </div>
+
+        <div class="col-md-5">
+            <div class="card">
+                <div class="card-header fw-semibold">Live Preview</div>
+                <div class="card-body preview-area @GetPreviewClasses()">
+                    <h5 style="@GetPreviewHeadingStyle()">Dashboard</h5>
+                    <p style="@GetPreviewTextStyle()">
+                        Welcome back! Here's an overview of your recent activity.
+                    </p>
+                    <div class="d-flex gap-2 mb-3">
+                        <span class="badge" style="@GetPreviewBadgeStyle()">Active</span>
+                        <span class="badge bg-secondary">3 tasks</span>
+                    </div>
+                    <div class="preview-card" style="@GetPreviewCardStyle()">
+                        <strong style="@GetPreviewTextStyle()">Sample Card</strong>
+                        <p class="mb-0 mt-1" style="@GetPreviewSmallTextStyle()">
+                            This is how content will look with your selected settings.
+                        </p>
+                    </div>
+                    <div class="mt-2 text-end">
+                        <small class="opacity-75" style="@GetPreviewSmallTextStyle()">
+                            🌐 @_language
+                        </small>
+                    </div>
+                </div>
+            </div>
+        </div>
+    </div>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public AppearanceSettings? Settings { get; set; }
+    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }
+
+    private AppearanceSettings? _settings;
+    private string _theme = "Light";
+    private string _fontSize = "Medium";
+    private string _language = "English";
+    private bool _compactMode;
+    private string? _message;
+    private bool _saving;
+
+    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];
+
+    protected override void OnParametersSet()
+    {
+        if (_settings is null && Settings is not null)
+        {
+            _settings = Settings;
+            _theme = Settings.Theme;
+            _fontSize = Settings.FontSize;
+            _language = Settings.Language;
+            _compactMode = Settings.CompactMode;
+        }
+    }
+
+    private string GetPreviewClasses()
+    {
+        var classes = _theme == "Dark" ? "preview-dark" : "preview-light";
+        if (_compactMode) classes += " preview-compact";
+        return classes;
+    }
+
+    private string GetFontSizePx() => _fontSize switch
+    {
+        "Small" => "13px",
+        "Large" => "18px",
+        _ => "15px"
+    };
+
+    private string GetPreviewTextStyle() =>
+        $"font-size: {GetFontSizePx()}; color: {(_theme == "Dark" ? "#e0e0e0" : "#333")};";
+
+    private string GetPreviewHeadingStyle() =>
+        $"color: {(_theme == "Dark" ? "#fff" : "#212529")};";
+
+    private string GetPreviewSmallTextStyle() =>
+        $"font-size: {(_fontSize == "Small" ? "11px" : _fontSize == "Large" ? "15px" : "13px")}; color: {(_theme == "Dark" ? "#adb5bd" : "#6c757d")};";
+
+    private string GetPreviewBadgeStyle() =>
+        $"background-color: {(_theme == "Dark" ? "#0d6efd" : "#198754")}; color: white;";
+
+    private string GetPreviewCardStyle() =>
+        $"background: {(_theme == "Dark" ? "#2d2d2d" : "#f8f9fa")}; border: 1px solid {(_theme == "Dark" ? "#444" : "#dee2e6")}; border-radius: 0.375rem; padding: {(_compactMode ? "0.5rem" : "1rem")};";
+
+    private async Task SaveAsync()
+    {
+        _saving = true;
+        _message = null;
+        try
+        {
+            var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+            await OnSave.InvokeAsync(updated);
+            _settings = updated;
+            _message = "Appearance settings saved!";
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

